+    BUSTER_A64_STORAGE_EXPECT(!buster_a64_semantic_unpack_block(S8("gVoBYmM=").pointer, 8, guarded + 1, 5, 2));
+    for (u32 index = 0; index < BUSTER_ARRAY_LENGTH(guarded); index += 1)
