     BUSTER_A64_STORAGE_EXPECT(buster_a64_semantic_blob_fill(&fixture, fixture_bytes, sizeof(fixture_bytes)));
     for (u32 index = 0; index < BUSTER_ARRAY_LENGTH(fixture_bytes); index += 1)
